const parts = require('fs').readFileSync(0, 'utf8').split(/\s+/).filter(Boolean).map(Number);
const n = parts.length ? parts[0] : 0;
const events = [];
for (let i = 0; i < n; i++) {
  events.push([parts[1 + i * 2], 1]);
  events.push([parts[2 + i * 2], -1]);
}
events.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
let open = 0;
let best = 0;
for (const [, delta] of events) {
  open += delta;
  if (open > best) best = open;
}
console.log(best);

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type event struct{ at, delta int }

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		fmt.Println(0)
		return
	}
	events := make([]event, 0, n*2)
	for i := 0; i < n; i++ {
		var start, end int
		if _, err := fmt.Fscan(in, &start, &end); err != nil {
			break
		}
		events = append(events, event{start, 1}, event{end, -1})
	}
	sort.Slice(events, func(i, j int) bool {
		if events[i].at != events[j].at {
			return events[i].at < events[j].at
		}
		return events[i].delta < events[j].delta
	})
	open, best := 0, 0
	for _, e := range events {
		open += e.delta
		if open > best {
			best = open
		}
	}
	fmt.Println(best)
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        if (!in.hasNextInt()) {
            System.out.println(0);
            return;
        }
        int n = in.nextInt();
        int[][] events = new int[n * 2][2];
        for (int i = 0; i < n; i++) {
            events[i * 2] = new int[] {in.nextInt(), 1};
            events[i * 2 + 1] = new int[] {in.nextInt(), -1};
        }
        Arrays.sort(events, (a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
        int open = 0;
        int best = 0;
        for (int[] e : events) {
            open += e[1];
            best = Math.max(best, open);
        }
        System.out.println(best);
    }
}

