const k = data[0];
const n = data[1];
const values = data.slice(2, 2 + n);
const window = [];
const out = [];
for (let i = 0; i < values.length; i++) {
  while (window.length && values[window[window.length - 1]] <= values[i]) window.pop();
  window.push(i);
  if (window[0] <= i - k) window.shift();
  if (i >= k - 1) out.push(values[window[0]]);
}
if (out.length) console.log(out.join('\n'));

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var k, n int
	if _, err := fmt.Fscan(in, &k, &n); err != nil {
		return
	}
	values := make([]int, 0, n)
	for i := 0; i < n; i++ {
		var v int
		if _, err := fmt.Fscan(in, &v); err != nil {
			break
		}
		values = append(values, v)
	}
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	window := make([]int, 0, len(values))
	for i, v := range values {
		for len(window) > 0 && values[window[len(window)-1]] <= v {
			window = window[:len(window)-1]
		}
		window = append(window, i)
		if window[0] <= i-k {
			window = window[1:]
		}
		if i >= k-1 {
			out.WriteString(strconv.Itoa(values[window[0]]))
			out.WriteByte('\n')
		}
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.StreamTokenizer;
import java.util.ArrayDeque;
import java.util.Deque;

public class Main {
    public static void main(String[] args) throws Exception {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        if (in.nextToken() == StreamTokenizer.TT_EOF) return;
        int k = (int) in.nval;
        in.nextToken();
        int n = (int) in.nval;
        int[] values = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            values[i] = (int) in.nval;
        }
        Deque<Integer> window = new ArrayDeque<>();
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            while (!window.isEmpty() && values[window.peekLast()] <= values[i]) window.pollLast();
            window.addLast(i);
            if (window.peekFirst() <= i - k) window.pollFirst();
            if (i >= k - 1) out.append(values[window.peekFirst()]).append('\n');
        }
        System.out.print(out);
    }
}
